package bench

import (
	"testing"

	"strix-halo-vulkan/vk"
)

// Temporary smoke test for the ROWS/NROWS grouped builds: it runs the same
// correctness check the timed arm runs, without the ten minutes of GEMM
// families in front of it.
func TestGroupedGEMVRowBlocks(t *testing.T) {
	instance, err := vk.NewInstance("rowblock-smoke")
	if err != nil {
		t.Skip(err)
	}
	defer instance.Destroy()
	devices, err := instance.PhysicalDevices()
	if err != nil || len(devices) == 0 {
		t.Skip(err)
	}
	phys := &devices[0]
	sgs, err := phys.SubgroupSizeControl()
	if err != nil {
		t.Fatal(err)
	}
	qf, err := phys.ComputeQueueFamily()
	if err != nil {
		t.Fatal(err)
	}
	dev, err := vk.NewDevice(phys, qf, vk.DeviceFeatures{
		Float16: true, Int8: true, IntegerDotProduct: true, CoopMatrix: true,
		SubgroupSizeControl: sgs.Supported,
	})
	if err != nil {
		t.Fatal(err)
	}
	defer dev.Destroy()

	for _, v := range moeGEMVVariants {
		if v.rowsPerWG() == 1 {
			continue
		}
		mod, err := dev.NewShaderModule(v.spirv)
		if err != nil {
			t.Fatalf("%s: %v", v.name, err)
		}
		if err := verifyMoEGroupedGEMV(dev, mod, v); err != nil {
			t.Errorf("%s: %v", v.name, err)
		}
		mod.Destroy()
	}
}
